from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Plan_create(EmssimCommand):
    def __init__(self, method="plan_create", timeout=60, rpc_connection_name='localRPC'):
        super(Plan_create, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Plan_create, self).on_new_data(**data)
        if "msg" in data:
            if data["msg"] == "Created empty configuration plan":
                self._ret['plan_created'] = 1
        elif ("status" in data):
            self._ret["status"] = data["status"]
